            self.ads.start_comparator(channel, threshold_high, threshold_low, pga=pga, sps=sps, active_low=active_low, traditional_mode=traditional_mode, latching=latching, num_readings=num_readings)
        except Exception as e:
            if self.debug:
                logging.error(f"Error starting single-ended comparator: {e}")

    def stop_all(self):
        try:
            self.ads.stop_adc_continuous()
            self.ads.stop_comparator()
        except Exception as e:
            if self.debug:
                logging.error(f"Error stopping ADC operations: {e}")

