import time
import logging
import sys
import signal
from gpiozero import Relay, MCP3008
from gpiozero.tools import pi_device_exists

# Set up logging
logging.basicConfig(level=logging.INFO)

class SmartGardenController:
    def __init__(self):
        self.mcp3008 = MCP3008(channel=0, spi=0)
        self.pump_relay = Relay(18, active_high=True)

    def read_moisture(self):
        try:
            return self.mcp3008.value
        except Exception as e:
            logging.error(f"Error reading moisture: {e}")
            return None

    def run_pump(self, seconds):
        try:
            self.pump_relay.on()
            time.sleep(seconds)
            self.pump_relay.off()
        except Exception as e:
            logging.error(f"Error running pump: {e}")

    def irrigation_cycle(self):
        moisture_value = self.read_moisture()
        if moisture_value is not None and moisture_value > 450:
            self.run_pump(2)
            return True
        return False

    def close(self):
        self.pump_relay.close()
        self.mcp3008.close()

def schedule_cycles(controller, cycle_count, interval_seconds):
    for _ in range(cycle_count):
        if controller.irrigation_cycle():
            logging.info("Irrigation cycle triggered.")
        time.sleep(interval_seconds)

def main():
    if not pi_device_exists('spi0.0'):
        logging.error("SPI bus not found.")
        sys.exit(1)

    try:
        controller = SmartGardenController()
        schedule_cycles(controller, 10, 3)
    except Exception as e:
        logging.error(f"Main error: {e}")
    finally:
        if hasattr(controller, 'close'):
            controller.close()

if __name__ == "__main__":
    signal.signal(signal.SIGINT, lambda *_: main())
    main()

