import argparse
import queue
import time
import logging
import threading
from gpiozero import DigitalInputDevice
from spidev import SpiDev
from adafruit_mcp3xxx.mcp3008 import MCP3008

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.spi = None
        self.digital_input = None
        self.last_reading = None
        self.last_time = time.time()

        if sensor_type == "digital":
            try:
                self.digital_input = DigitalInputDevice(self.gpio_pins[sensor_id], pull_up=True)
            except Exception as e:
                logging.error(f"Error setting up digital GPIO for sensor {sensor_id}: {e}")

        elif sensor_type == "analog":
            try:
                self.spi = SpiDev()
                self.spi.open(0, 0)
                self.spi.max_speed_hz = self.spi_speed
                self.adc = MCP3008(spi=self.spi)
            except Exception as e:
                logging.error(f"Error initializing SPI for sensor {sensor_id}: {e}")

    def read(self):
        if self.sensor_type == "digital":
            try:
                reading = self.digital_input.value
            except Exception as e:
                logging.error(f"Error reading digital GPIO for sensor {self.sensor_id}: {e}")
                return None
        elif self.sensor_type == "analog":
            try:
                reading = self.adc.read_adc(self.channels[self.sensor_id])
            except Exception as e:
                logging.error(f"Error reading analog ADC for sensor {self.sensor_id}: {e}")
                return None

        return reading

    def run(self):
        while True:
            reading = self.read()
            if reading is not None:
                if (self.sensor_type == "digital" and reading == 1) or (self.sensor_type == "analog" and reading >= self.threshold):
                    if time.time() - self.last_time >= 0.1:
                        self.last_time = time.time()
                        self.last_reading = reading
                        if self.log_queue:
                            self.log_queue.put(f"Sensor {self.sensor_id} detected sound at {self.last_reading}")

            time.sleep(1 / self.sample_rate)

    def stop(self):
        if self.sensor_type == "analog":
            self.spi.close()
        if self.sensor_type == "digital":
            self.digital_input.close()

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--sensor_type", type=str, required=True)
    parser.add_argument("--threshold", type=int, required=True)
    parser.add_argument("--sample_rate", type=int, required=True)
    parser.add_argument("--log_file", type=str, required=True)
    parser.add_argument("--gpio_pins", type=int, nargs='+', required=True)
    parser.add_argument("--channels", type=int, nargs='+', required=True)
    parser.add_argument("--spi_speed", type=int, default=1000000)
    parser.add_argument("--sensor_ids", type=int, nargs='+', required=True)
    args = parser.parse_args()

    logging.basicConfig(filename=args.log_file, level=logging.ERROR)
    log_queue = queue.Queue()

    sensors = []
    for sensor_id in args.sensor_ids:
        sensors.append(SoundSensor(sensor_id, args.sensor_type, args.threshold, args.sample_rate, args.gpio_pins, args.channels, args.spi_speed, log_queue))

    threads = []
    for sensor in sensors:
        thread = threading.Thread(target=sensor.run)
        thread.start()
        threads.append(thread)

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        for sensor in sensors:
            sensor.stop()
        for thread in threads:
            thread.join()

if __name__ == "__main__":
    main()

