import time
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

class ADS1115:
    def __init__(self):
        self.i2c = busio.I2C(board.SCL, board.SDA)
        self.ads = ADS.ADS1115(self.i2c)
        self.channels = {
            0: self.ads.SINGLE_ENDED_0,
            1: self.ads.SINGLE_ENDED_1,
            2: self.ads.SINGLE_ENDED_2,
            3: self.ads.SINGLE_ENDED_3
        }
        self.pga_settings = {
            "6144": self.ads.P0,
            "4096": self.ads.P1,
            "2048": self.ads.P2,
            "1024": self.ads.P3,
            "512": self.ads.P4,
            "256": self.ads.P5
        }

    def read(self, channel, pga):
        if channel not in self.channels:
            raise ValueError(f"Invalid channel: {channel}. Must be 0-3.")
        if pga not in self.pga_settings:
            raise ValueError(f"Invalid PGA setting: {pga}. Must be 6144, 4096, 2048, 1024, 512, or 256 mV.")

        try:
            adc = AnalogIn(self.i2c, self.channels[channel], gain=self.pga_settings[pga])
            time.sleep(0.01)  # Wait 10 ms for conversion to complete
            raw_value = adc.value
            scaled_value = raw_value * (self.pga_settings[pga] / 32768) * 1000  # Convert to millivolts
            return scaled_value
        except Exception as e:
            print(f"Error: {e}")
            return None

    def __del__(self):
        self.i2c.deinit()

# Example usage
