import logging
import signal
from PIL import Image
from gpiozero import Display
from PIL.GifImagePlugin import getheader, getdata
from PIL.ImageOps import pad

logging.basicConfig(level=logging.INFO)

class AnimatedGif:
    def __init__(self, display, width=None, height=None, folder_path=None):
        self.display = display
        self.width = width or display.width
        self.height = height or display.height
        self.folder_path = folder_path
        self.frames = []
        self._is_running = False
        self.loop_count = 0

    def load_files(self):
        valid_gifs = []
        for filename in os.listdir(self.folder_path):
            if filename.endswith(".gif"):
                try:
                    with Image.open(os.path.join(self.folder_path, filename)) as img:
                        if img.format == "GIF":
                            valid_gifs.append(filename)
                        else:
                            logging.warning(f"File {filename} is not an animated GIF.")
                except Exception as e:
                    logging.error(f"Error loading {filename}: {e}")

        if not valid_gifs:
            raise FileNotFoundError("No valid GIFs found in the specified folder.")

        self.frames = [os.path.join(self.folder_path, gif) for gif in valid_gifs]

    def preload(self):
        for frame in self.frames:
            with Image.open(frame) as img:
                duration, loop = getheader(img)[6]
                self.loop_count = loop
                frame_rgb = img.convert("RGB")
                padded_frame = pad(frame_rgb, (self.width, self.height), color="black", method="constant")
                self.frames.append((padded_frame, duration))

    def play(self):
        try:
            for frame, duration in self.frames:
                self.display.display(frame)
                elapsed = time.monotonic()
                sleep_time = max(0, duration / 1000 - (time.monotonic() - elapsed))
                time.sleep(sleep_time)
            return True
        except Exception as e:
            logging.error(f"Error playing GIF: {e}")
            return False

    def run(self):
        self._is_running = True
        while self._is_running:
            if self.play():
                self._is_running = False

    def stop(self):
        self._is_running = False

    def __del__(self):
        if self._is_running:
            self.stop()
            logging.info("Animation stopped on object deletion.")

def signal_handler(sig, frame):
    logging.info("Received SIGINT or SIGTERM, stopping animation.")
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

