from gpiozero.tools import debounce

GPIO_LIGHT_SENSOR_PIN = 17
GPIO_TEMP_SENSOR_PIN = 4
LOW_LIGHT_THRESHOLD = 300
HIGH_TEMP_THRESHOLD = 35
HIGH_PI_TEMP_THRESHOLD = 75

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(message)s')

def simulate_light_sensor():
    try:
        now = datetime.datetime.now()
        hour = now.hour
        if 6 <= hour < 18:  # Daylight
            return round(random.uniform(600, 1000), 2)
        else:  # Nighttime
            return round(random.uniform(100, 300), 2)
    except Exception as e:
        logging.error(f"Error simulating light sensor: {e}")
        return 0

def simulate_temperature_sensor():
    try:
        return round(random.uniform(20, 30), 2)
    except Exception as e:
        logging.error(f"Error simulating temperature sensor: {e}")
        return 0

def read_pi_temperature():
    try:
        result = subprocess.run(['vcgencmd', 'measure_temp'], stdout=subprocess.PIPE, timeout=5)
        output = result.stdout.decode('utf-8').strip()
        if 'temp=' in output:
            temp_str = output.split('=')[1].strip("'C")
            return float(temp_str)
        else:
            logging.warning("Failed to read Pi temperature, using default.")
            return None
    except Exception as e:
        logging.error(f"Error reading Pi temperature: {e}")
        return None

def log_data(lux, temp, voltage, current, pi_temp):
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    logging.info(f"{timestamp} - Light: {lux} lux, Temp: {temp} °C, Voltage: {voltage} V, Current: {current} A, Pi Temp: {pi_temp} °C")

def setup_sensors():
    factory = PiGPIOFactory()
    light_sensor = LightSensor(GPIO_LIGHT_SENSOR_PIN, pin_factory=factory)
    temp_sensor = TemperatureSensor(GPIO_TEMP_SENSOR_PIN, pin_factory=factory)
    return light_sensor, temp_sensor

def main():
    light_sensor, temp_sensor = setup_sensors()
    try:
        while True:
            lux = simulate_light_sensor()
            temp = simulate_temperature_sensor()
            pi_temp = read_pi_temperature()

            if lux < LOW_LIGHT_THRESHOLD:
                logging.warning("Light level is below the LOW_LIGHT_THRESHOLD.")
            if temp > HIGH_TEMP_THRESHOLD:
                logging.warning("Temperature exceeds the HIGH_TEMP_THRESHOLD. Simulating cooling activation.")
            if pi_temp is not None and pi_temp > HIGH_PI_TEMP_THRESHOLD:
                logging.critical("Pi internal temperature exceeds the HIGH_PI_TEMP_THRESHOLD. Simulating system shutdown.")
                sys.exit(1)

            voltage = 11.5 if lux > 300 else 10.5
            current = 2.5 if lux > 300 else 0.75

            log_data(lux, temp, voltage, current, pi_temp)
            time.sleep(5)
    except KeyboardInterrupt:
        logging.info("Gracefully terminating the program.")
    finally:
        light_sensor.close()
        temp_sensor.close()

