GPIO.setup(4, GPIO.IN, pull_up_down=GPIO.PUD_UP)
GPIO.setup(17, GPIO.OUT, initial=GPIO.HIGH)

def control_led(temperature):
    if temperature > 30.0:
        GPIO.output(17, GPIO.LOW)
        return "ON"
    elif temperature < 27.0:
        GPIO.output(17, GPIO.HIGH)
        return "OFF"
    else:
        return "NO_CHANGE"

def send_data(temperature, humidity):
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.connect(('192.168.1.100', 12345))
            s.sendall(f"{temperature:.1f},{humidity:.1f}".encode())
    except Exception as e:
        print(f"Error sending data: {e}")

def read_dht22():
    GPIO.output(4, GPIO.LOW)
    time.sleep(0.017)
    GPIO.output(4, GPIO.HIGH)

    data = []
    while True:
        GPIO.wait_for_edge(4, GPIO.RISING)
        pulse_start = time.time()
        while GPIO.input(4) == GPIO.HIGH:
            pass
        pulse_end = time.time()
        pulse_duration = pulse_end - pulse_start

        if pulse_duration < 0.00008:
            data.append(0)
        else:
            data.append(1)

        if len(data) == 40:
            break

    if len(data) != 40:
        print("Sensor absence or bus error detected.")
        return None, None

    humidity = struct.unpack('<H', bytes(data[0:16]))[0]
    temperature = struct.unpack('<H', bytes(data[16:32]))[0]
    checksum = sum(data[0:39]) & 0xFF

    if checksum != data[39]:
        print("Checksum error detected.")
        return None, None

    temperature = temperature / 10.0
    humidity = humidity / 10.0

    return temperature, humidity

