factory = PiGPIOFactory()

class FanController:
    def __init__(self, pin):
        self.fan = PWMLED(pin, factory=factory)
        self.temperature_thresholds = {
            'low': 40,  # Celsius
            'medium': 50,
            'high': 60
        }
        self.duty_cycles = {
            'low': 0.2,
            'medium': 0.5,
            'high': 0.8
        }

    def read_temperature(self):
        try:
            with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
                temperature = int(f.read().strip()) / 1000
        except IOError:
            try:
                temperature = float(os.popen('vcgencmd measure_temp').readline().replace('temp=', '').replace('\'C\n', ''))
            except Exception as e:
                print(f"Error reading temperature: {e}")
                return None
        return temperature

    def set_fan_speed(self, temperature):
        if temperature is None:
            return
        if temperature < self.temperature_thresholds['low']:
            duty_cycle = 0
        elif temperature < self.temperature_thresholds['medium']:
            duty_cycle = self.duty_cycles['low']
        elif temperature < self.temperature_thresholds['high']:
            duty_cycle = self.duty_cycles['medium']
        else:
            duty_cycle = self.duty_cycles['high']
        self.fan.value = duty_cycle

    def run(self):
        while True:
            temperature = self.read_temperature()
            if temperature is not None:
                print(f"Temperature: {temperature}°C, Fan Speed: {self.fan.value * 100}%")
            time.sleep(5)

