import datetime
import os
import smbus
from datetime import datetime

# BME280 I2C address
BME280_ADDRESS = 0x76

# BME280 Registers
BME280_REGISTER_HUMIDITY = 0xF2

# Comfort bands
comfort_bands = {
    "<30": "too_dry",
    "30-40": "dry",
    "40-60": "comfortable",
    ">60": "too_humid"
}

def read_humidity():
    try:
        bus = smbus.SMBus(1)  # I2C bus 1
        humidity_raw = bus.read_byte_data(BME280_ADDRESS, BME280_REGISTER_HUMIDITY)
        bus.close()
        return humidity_raw
    except OSError as e:
        print(f"Error reading humidity: {e}")
        return None

def classify_humidity(humidity_raw):
    if humidity_raw is None:
        return None
    humidity_percentage = humidity_raw / 100.0
    for band, classification in comfort_bands.items():
        lower, upper = map(float, band.split('-'))
        if lower <= humidity_percentage < upper:
            return classification
    return "unknown"

def main():
    try:
        for _ in range(5):
            humidity_raw = read_humidity()
            if humidity_raw is not None:
                classification = classify_humidity(humidity_raw)
                timestamp = datetime.now().isoformat(timespec='seconds')
                print(f"Timestamp: {timestamp}, Humidity: {humidity_raw}, Classification: {classification}")
            time.sleep(2)
    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
    main()

