LED_PIN = 17

# Initialize GPIO
def setup_gpio():
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT)
        GPIO.output(LED_PIN, GPIO.LOW)
        return True
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        return False

# Cleanup GPIO
def cleanup_gpio():
    GPIO.output(LED_PIN, GPIO.LOW)
    GPIO.cleanup()

# Main program loop
