import time
import signal
import sys
from datetime import datetime
from gpiozero import MotionSensor

class OccupancyMonitor:
    def __init__(self, pin, debounce_interval=2.0, sample_count=10):
        self.pin = pin
        self.debounce_interval = debounce_interval
        self.sample_count = sample_count
        self.events = []
        self.last_event_time = None
        self.sensor = None

    def _initialize_sensor(self):
        try:
            self.sensor = MotionSensor(self.pin, active_high=True)
            self.sensor.wait_for_motion()
        except Exception as e:
            print(f"Error initializing sensor: {e}")
            return False
        return True

    def _handle_signal(self, signum, frame):
        print("Received signal, cleaning up...")
        self.sensor.close()
        sys.exit(0)

    def _log_event(self):
        if self.last_event_time is None or (datetime.now() - self.last_event_time).total_seconds() >= self.debounce_interval:
            self.events.append(datetime.now().isoformat())
            self.last_event_time = datetime.now()

    def start_polling(self):
        if not self._initialize_sensor():
            sys.exit(1)

        signal.signal(signal.SIGINT, self._handle_signal)
        signal.signal(signal.SIGTERM, self._handle_signal)

        try:
            while len(self.events) < self.sample_count:
                if self.sensor.motion_detected:
                    self._log_event()
                time.sleep(0.5)
        except Exception as e:
            print(f"Runtime error: {e}")
            self.sensor.close()
            sys.exit(1)

        self.sensor.close()
        print("Polling finished.")
        self._print_summary()

    def _print_summary(self):
        print(f"Total events detected: {len(self.events)}")
        for event in self.events:
            print(event)

if __name__ == "__main__":
    monitor = OccupancyMonitor(17)
    monitor.start_polling()
