import logging
import signal
import time
from typing import Callable
from gpiozero import PWMLED, DigitalOutputDevice
from zmq import Context, Socket

class PIDHandler:
    def __init__(self, pwm_pin: int = 12, digital_pin: int = 10, pwm_freq: int = 1000):
        self.pwm_pin = pwm_pin
        self.digital_pin = digital_pin
        self.pwm_freq = pwm_freq
        self.pwm_flag = True
        self.global_err_state = False
        self.last_msg = time.time()
        self.context = Context()
        self.socket = self.context.socket(Socket.SUB)
        self.socket.connect("tcp://localhost:5555")
        self.socket.setsockopt_string(Socket.SUBSCRIBE, b"")
        self.pwm_output = None
        self.digital_output = None
        self.setup_gpio()

    def setup_gpio(self):
        try:
            self.pwm_output = PWMLED(self.pwm_pin, frequency=self.pwm_freq)
            self.digital_output = DigitalOutputDevice(self.digital_pin)
        except Exception as e:
            logging.error(f"Failed to initialize GPIO: {e}")
            self.cleanup()
            raise

    def cleanup(self):
        if self.pwm_output:
            self.pwm_output.close()
        if self.digital_output:
            self.digital_output.close()
        self.socket.close()

    def update_error_output(self):
        if self.pwm_flag:
            self.pwm_output.value = self.global_err_state
        else:
            self.digital_output.value = self.global_err_state

    def set_error_output(self, state: bool):
        self.global_err_state = state
        self.update_error_output()

    def handle_message(self, callback: Callable):
        try:
            message = self.socket.recv()
            if message:
                self.last_msg = time.time()
                callback(message)
        except Exception as e:
            logging.error(f"Error receiving message: {e}")

    def watchdog(self):
        if time.time() - self.last_msg > 20:
            self.set_error_output(True)
            logging.warning("Watchdog timeout, error output set to True")

    def run(self, callback: Callable):
        signal.signal(signal.SIGINT, self.signal_handler)
        signal.signal(signal.SIGTERM, self.signal_handler)

        while True:
            self.handle_message(callback)
            self.watchdog()
            time.sleep(1)

    def signal_handler(self, signal, frame):
        logging.info("Received signal, cleaning up...")
        self.cleanup()
        exit(0)

# Example usage:
def example_callback(message):
    logging.info(f"Received message: {message.decode()}")

handler = PIDHandler()
handler.run(example_callback)

