import RPi.GPIO as GPIO
import time
import signal
import logging

class RotaryEncoder:
    def __init__(self, clk_pin=17, dt_pin=18, callback=None):
        self.clk_pin = clk_pin
        self.dt_pin = dt_pin
        self.callback = callback
        self.counter = 0
        self.last_state = 0
        self.last_clk = 0
        self.last_dt = 0

        GPIO.setmode(GPIO.BCM)
        GPIO.setup(self.clk_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(self.dt_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)

        GPIO.add_event_detect(self.clk_pin, GPIO.BOTH, callback=self._handle_clk, bouncetime=20)
        GPIO.add_event_detect(self.dt_pin, GPIO.BOTH, callback=self._handle_dt, bouncetime=20)

        if callable(self.callback):
            self.callback(self.counter)

    def _handle_clk(self, channel):
        try:
            self.last_clk = GPIO.input(self.clk_pin)
            self._update_counter()
        except Exception as e:
            logging.error(f"Error handling CLK event: {e}")

    def _handle_dt(self, channel):
        try:
            self.last_dt = GPIO.input(self.dt_pin)
            self._update_counter()
        except Exception as e:
            logging.error(f"Error handling DT event: {e}")

    def _update_counter(self):
        current_state = (self.last_clk << 1) | self.last_dt
        transition = current_state - self.last_state

        if transition == 1 or transition == -3:
            self.counter += 1
        elif transition == -1 or transition == 3:
            self.counter -= 1

        self.last_state = current_state

        if self.callback:
            self.callback(self.counter)

    def cleanup(self):
        GPIO.remove_event_detect(self.clk_pin)
        GPIO.remove_event_detect(self.dt_pin)
        GPIO.cleanup()

    def __del__(self):
        self.cleanup()

def signal_handler(sig, frame):
    logging.info("Received signal, cleaning up...")
    encoder.cleanup()
    exit(0)

def main():
    global encoder
    encoder = RotaryEncoder(callback=lambda counter: print(f"Counter: {counter}"))

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        logging.info("Keyboard interrupt, cleaning up...")
        encoder.cleanup()

if __name__ == "__main__":
    main()

