import time
import RPi.GPIO as GPIO
from gpiozero import RotaryEncoder

class CustomRotaryEncoder(RotaryEncoder):
    def __init__(self, clk_pin=17, dt_pin=18, callback=None, debounce_time=0.005):
        super().__init__(clk_pin, dt_pin, callback=callback, debounce_time=debounce_time)
        self.clk_pin = clk_pin
        self.dt_pin = dt_pin
        self.counter = 0

        if not callable(callback):
            raise ValueError("Callback must be callable.")

        self.callback = callback

    def _on_change(self, change):
        try:
            if change == 1:
                self.counter += 1
            elif change == -1:
                self.counter -= 1
            if self.callback:
                self.callback(self.counter)
        except Exception as e:
            print(f"Error invoking callback: {e}")

    def cleanup(self):
        GPIO.cleanup(self.clk_pin)
        GPIO.cleanup(self.dt_pin)

def main():
    try:
        encoder = CustomRotaryEncoder(clk_pin=17, dt_pin=18, callback=lambda counter: print(f"Counter: {counter}"))
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        print("KeyboardInterrupt caught, cleaning up.")
    finally:
        if encoder:
            encoder.cleanup()

if __name__ == "__main__":
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(17, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    GPIO.setup(18, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    main()

