    "DiskIO": {"Red": LED(led_pins["DiskIO"]["Red"]), "Green": LED(led_pins["DiskIO"]["Green"]), "Blue": LED(led_pins["DiskIO"]["Blue"])}
}

# PWM devices
pwm_devices = {
    "CPU": {"Red": pwm_device(led_pins["CPU"]["Red"], frequency=PWM_FREQ), "Green": pwm_device(led_pins["CPU"]["Green"], frequency=PWM_FREQ), "Blue": pwm_device(led_pins["CPU"]["Blue"], frequency=PWM_FREQ)},
