}

# Exponential backoff for reconnection
backoff_time = 1
max_backoff_time = 60

# Lock for shared data
lock = threading.Lock()

# Function to map usage to PWM duty cycle
def map_usage_to_duty_cycle(usage):
    if usage > 66:
        return 1 - (usage - 66) / 34
    elif usage > 33:
        return (usage - 33) / 33
    else:
