import time
import signal
import sys
from gpiozero import LED

class LEDController:
    def __init__(self, pin):
        try:
            self.led = LED(pin)
        except ValueError:
            print(f"Error: Invalid pin number {pin}. Please use a valid GPIO pin.")
            sys.exit(1)

    def on(self):
        self.led.on()

    def off(self):
        self.led.off()

    def blink(self, on_duration, off_duration):
        if on_duration < 0 or off_duration < 0:
            print("Error: On and off durations must be non-negative.")
            return

        self.led.blink(on_duration, off_duration)

    def cleanup(self, signum, frame):
        self.led.off()
        print("Cleanup: LED turned off and GPIO resources released.")
        sys.exit(0)

    def __del__(self):
        self.led.off()
        print("Cleanup: LED turned off and GPIO resources released.")

def main():
    controller = LEDController(25)

    signal.signal(signal.SIGINT, controller.cleanup)
    signal.signal(signal.SIGTERM, controller.cleanup)

    while True:
        try:
            controller.blink(1.0, 0.5)
        except Exception as e:
            print(f"Error: {e}")
            controller.cleanup(None, None)

if __name__ == "__main__":
    main()

