import time
import logging
import signal
import sys
from gpiozero import MotionSensor
from gpiozero.tools import debounce

class MotionDetector:
    def __init__(self, sensor_pin):
        self.sensor_pin = sensor_pin
        self.sensor = MotionSensor(self.sensor_pin, bounce_time=0.2)
        self.visitor_count = 0
        self.last_detection = time.time()
        self.absent_timeout = 30  # seconds
        self.logging_setup()

    def logging_setup(self):
        logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

    def poll_sensor(self):
        if self.sensor.motion_detected:
            self.visitor_count += 1
            self.last_detection = time.time()
            logging.info(f"Visitor detected. Total visitors: {self.visitor_count}")

    def check_absent_condition(self):
        if time.time() - self.last_detection > self.absent_timeout:
            logging.info("No motion detected for 30 seconds. Assuming no visitors.")
            self.visitor_count = 0

    def cleanup(self):
        self.sensor.close()
        logging.info("GPIO resources released.")

    def run(self):
        signal.signal(signal.SIGINT, self.signal_handler)
        signal.signal(signal.SIGTERM, self.signal_handler)

        try:
            while True:
                self.poll_sensor()
                self.check_absent_condition()
                time.sleep(1)
                if time.time() % 10 == 0:
                    logging.info(f"Intermediate tally: {self.visitor_count} visitors")
                if time.time() >= 60:
                    logging.info(f"Final tally: {self.visitor_count} visitors in 60 seconds")
                    break
        except Exception as e:
            logging.error(f"An error occurred: {e}")
        finally:
            self.cleanup()

    def signal_handler(self, signal, frame):
        logging.info("Received signal. Cleaning up and exiting.")
        self.cleanup()
        sys.exit(0)

if __name__ == "__main__":
    detector = MotionDetector(23)
    detector.run()

