import RPi.GPIO as GPIO
from gpiozero import PWMOutputDevice
from gpiozero.exceptions import DeviceDisconnectedError

class MotorError(Exception):
    pass

class Motor:
    def __init__(self, driver_lib, pin_number):
        self.driver_lib = driver_lib
        self.pin_number = pin_number
        self.pwm = PWMOutputDevice(pin_number, frequency=1000, initial_value=0)
        self.set_duty_cycle(0)

    def set_frequency(self, freq):
        try:
            if self.driver_lib.set_frequency(freq) != 0:
                raise MotorError("Failed to set frequency")
            self.pwm.frequency = freq
        except DeviceDisconnectedError:
            raise MotorError("Driver library is disconnected")

    def set_duty_cycle(self, duty):
        if not 0 <= duty <= 255:
            raise MotorError("Duty cycle out of bounds (0-255)")
        try:
            if self.driver_lib.set_duty_cycle(duty) != 0:
                raise MotorError("Failed to set duty cycle")
            self.pwm.value = duty / 255
        except DeviceDisconnectedError:
            raise MotorError("Driver library is disconnected")

    def stop(self):
        self.set_duty_cycle(0)

    def __del__(self):
        self.stop()
        self.pwm.close()
        GPIO.cleanup(self.pin_number)

    def close(self):
        self.stop()
        self.pwm.close()
        GPIO.cleanup(self.pin_number)

