class ServoController:
    def __init__(self, pin):
        self.pin = pin
        self.servo = PWMOutputDevice(pin, frequency=50)
        self._angle_to_duty_cycle = {
            0: 2.5,
            45: 3.5,
            90: 5.0,
            135: 6.5,
            180: 7.5
        }

    def move_to(self, angle):
        duty_cycle = self._angle_to_duty_cycle.get(angle, 2.5)
        self.servo.value = duty_cycle / 10.0
        logging.info(f"Moved servo to {angle} degrees at {time.time()}")

    def stop(self):
        self.servo.value = 0
        logging.info("Stopped servo at {time.time()}")

    def __del__(self):
        self.stop()
        GPIO.cleanup()

