            controller.stop()

if __name__ == "__main__":
    try:
        angles = [0, 45, 90, 135, 180] + list(reversed(angles))
        servo_sweep(angles)
    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt caught, stopping servo.")
