from gpiozero import AngularServo
from gpiozero.exc import OutputDeviceBadValue, PinConflict, RuntimeError

class RoboticArm:
    def __init__(self, base_pin, shoulder_pin, gripper_pin):
        self.base = AngularServo(base_pin, min_pulse_width=0.5, max_pulse_width=2.5, frequency=50)
        self.shoulder = AngularServo(shoulder_pin, min_pulse_width=0.5, max_pulse_width=2.5, frequency=50)
        self.gripper = AngularServo(gripper_pin, min_pulse_width=0.5, max_pulse_width=2.5, frequency=50)

    def move_joint(self, joint, target_angle):
        try:
            joint.angle = target_angle
            time.sleep(0.4)  # Wait for settling
        except OutputDeviceBadValue:
            print(f"Invalid angle {target_angle} for joint {joint.pin}")
        except ValueError:
            print(f"Pin conflict for joint {joint.pin}")
        except RuntimeError:
            print(f"GPIO allocation failure for joint {joint.pin}")

    def go_to_pose(self, base_angle, shoulder_angle, gripper_angle):
        print(f"Moving to pose: base={base_angle}, shoulder={shoulder_angle}, gripper={gripper_angle}")
        self.move_joint(self.base, base_angle)
        self.move_joint(self.shoulder, shoulder_angle)
        self.move_joint(self.gripper, gripper_angle)

    def run_demo_sequence(self):
        poses = [(0, 0, 0), (45, -30, 20), (-45, 30, -20)]
        for pose in poses:
            self.go_to_pose(*pose)
        self.go_to_pose(0, 0, 0)

    def __del__(self):
        self.release()

    def release(self):
        self.base.angle = None
        self.shoulder.angle = None
        self.gripper.angle = None

def signal_handler(sig, frame):
    print("Caught signal, cleaning up...")
    arm.release()
