import struct
from typing import Optional, Union

class ESP8266:
    def __init__(self, port='/dev/serial0', baud_rate=115200, timeout=1.0):
        self.port = port
        self.baud_rate = baud_rate
        self.timeout = timeout
        self.ser = None
        self._open_port()

    def _open_port(self):
        try:
            self.ser = serial.Serial(self.port, self.baud_rate, timeout=self.timeout)
            print(f"Connected to {self.port} at {self.baud_rate} baud")
        except Exception as e:
            print(f"Failed to open {self.port}: {e}")

    def _send_command(self, command: bytes, terminator: bytes = b'OK', timeout=None) -> Optional[bytes]:
        if timeout is None:
            timeout = self.timeout
        self.ser.write(command)
        start_time = time.time()
        while True:
            response = self.ser.readline().strip()
            if response == terminator:
                return response
            if time.time() - start_time > timeout:
                return None

    def test_connection(self):
        return self._send_command(b'AT') == b'OK'

    def restart(self):
        self._send_command(b'AT+RST')
        time.sleep(2)
        if not self.test_connection():
            print("ESP8266 did not reboot successfully.")

    def connect_wifi(self, ssid: str, password: str, timeout=10.0):
        command = (
            f"AT+CWJAP='{ssid}','{password}'\r\n"
        ).encode()
        return self._send_command(command, timeout=timeout)

    def disconnect_wifi(self):
        return self._send_command(b'AT+CWQAP')

    def get_ip(self):
        response = self._send_command(b'AT+CIFSR')
        if response is not None:
            ip_start = response.find(b'STAIP:') + len(b'STAIP:')
            ip_end = response.find(b'\r\n', ip_start)
            return response[ip_start:ip_end].decode()
        return None

    def send_http_request(self, method: str, url: str, host: str, port: int = 80, headers: Optional[dict] = None, data: Optional[str] = None):
        start_command = f"AT+CIPSTART='TCP',{host},{port}\r\n"
        self._send_command(start_command.encode())
        if headers:
            for header, value in headers.items():
                self._send_command((f"AT+CIPSEND={len(header.encode()) + len(value.encode())}\r\n{header}: {value}\r\n").encode())
        if data:
            self._send_command((f"AT+CIPSEND={len(data.encode())}\r\n{data}\r\n").encode())
        return self.receive_http_response()

    def receive_http_response(self, timeout=5.0):
        start_time = time.time()
        while True:
            response = self.ser.readline().strip()
            if response.startswith(b'+IPD,'):
                length, _ = struct.unpack('!H', response[4:6])
                payload = self.ser.read(length).strip()
                return payload
            if time.time() - start_time > timeout:
                return None

    def __del__(self):
        self.close()

    def close(self):
        if self.ser:
            self.ser.close()
            print("Closed serial port")

def signal_handler(sig, frame):
    print("Closing serial port on exit.")
    esp.close()
    sys.exit(0)

