import serial
import time
import sys

def parse_gprmc(sentence):
    fields = sentence.split(',')
    if len(fields) >= 9 and fields[2] == 'A':  # Check if status is 'A'
        lat = float(fields[3]) + float(fields[4]) / 60
        lon = float(fields[5]) + float(fields[6]) / 60
        if fields[7] == 'S':  # South latitude
            lat = -lat
        if fields[8] == 'W':  # West longitude
            lon = -lon
        return lat, lon
    return None, None

def main():
    try:
        gps_port = serial.Serial('/dev/serial0', 9600, timeout=1)
        print("GPS module connected.")

        while True:
            try:
                gps_data = gps_port.readline().decode('utf-8').strip()
                if gps_data.startswith('$GPRMC'):
                    lat, lon = parse_gprmc(gps_data)
                    if lat is not None and lon is not None:
                        print(f"Latitude: {lat}, Longitude: {lon}")
            except (serial.SerialException, ValueError) as e:
                print(f"Error reading GPS data: {e}")
            time.sleep(1)

    except KeyboardInterrupt:
        print("\nInterrupted by user. Cleaning up...")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        if gps_port.is_open:
            gps_port.close()
            print("GPS module disconnected.")
        sys.exit(0)

