class ESP8266:
    def __init__(self):
        self.ser = None
        self.port = serial.Serial(
            port='/dev/ttyAMA0',
            baudrate=115200,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=5,
            xonxoff=False,
            rtscts=False,
            dsrdtr=False
        )
        if not self.ser.isOpen():
            try:
                self.ser.open()
            except serial.SerialException:
                print("Failed to open serial port.")
                sys.exit(1)

    def _send_command(self, command, delay=1, max_retries=3):
        for _ in range(max_retries):
            self.ser.write(command.encode())
            time.sleep(delay)
            response = self._read_response()
            if response in ["OK", "ERROR", "FAIL"]:
                return response
        return None

    def _read_response(self):
        response = ""
        start_time = time.time()
        while True:
            if self.ser.in_waiting > 0:
                data = self.ser.readline().decode().strip()
                response += data
                if "OK" in response or "ERROR" in response or "FAIL" in response:
                    return response
            if time.time() - start_time > 5:
                return None

    def test_connection(self):
        return self._send_command("AT\r\n") == "OK"

    def restart(self):
        return self._send_command("AT+RST\r\n", delay=2) == "OK"

    def connect_wifi(self, ssid, password):
        command = f"AT+CWJAP_CUR=\"{ssid}\",\"{password}\"\r\n"
        return "WIFI GOT IP" in self._send_command(command, delay=5)

    def __del__(self):
        if self.ser and self.ser.isOpen():
            self.ser.close()


def signal_handler(sig, frame):
    print("Exiting...")
