import serial
import time
import signal
from contextlib import contextmanager

class GPSModule:
    def __init__(self, port='/dev/ttyAMA0', baud=9600):
        self.port = port
        self.baud = baud
        self.ser = None

        try:
            self.ser = serial.Serial(port=self.port, baudrate=self.baud, timeout=1)
        except serial.SerialException as e:
            raise IOError(f"Failed to open port {self.port}: {e}")

    def attach(self):
        try:
            self.ser.write(b"AT+CGNSPWR=1\r\n")
            time.sleep(1)
            if self.ser.in_waiting > 0:
                response = self.ser.readline().decode().strip()
                if "OK" in response:
                    return True
                else:
                    raise ValueError(f"Failed to power on GNSS: {response}")
            else:
                raise ValueError("No response from GNSS after powering on")
        except Exception as e:
            raise IOError(f"Failed to attach GNSS: {e}")

    def detach(self):
        try:
            self.ser.write(b"AT+CGNSPWR=0\r\n")
            if self.ser.in_waiting > 0:
                response = self.ser.readline().decode().strip()
                if "OK" in response:
                    return True
                else:
