import serial
import logging
import sys
import time

# Configure logging
logging.basicConfig(level=logging.INFO)

class SimpleGPS:
    def __init__(self, port='/dev/serial0', baudrate=9600):
        self.port = port
        self.baudrate = baudrate
        self.ser = None

    def connect(self):
        try:
            self.ser = serial.Serial(self.port, self.baudrate, timeout=1)
            return True
        except OSError as e:
            logging.error(f"Failed to open serial port: {e}")
            return False

    def read_data(self):
        if self.ser is None:
            return None
        try:
            data = self.ser.readline().decode('utf-8', 'ignore').strip()
            return data
        except Exception as e:
            logging.error(f"Failed to read data: {e}")
            return None

    def parse_gga(self, line):
        if not line.startswith('$GPGGA') and not line.startswith('$GNGGA'):
            return None

        try:
            fields = line.split(',')
            utc_time = fields[1].split('.')[0]
            latitude = float(fields[2]) / 100 + float(fields[3]) / 600000 if fields[2] and fields[3] else None
            longitude = float(fields[4]) / 100 + float(fields[5]) / 600000 if fields[4] and fields[5] else None
            fix_quality = int(fields[6])
            num_satellites = int(fields[7])
            return {
                'utc_time': utc_time,
                'latitude': latitude,
                'longitude': longitude,
                'fix_quality': fix_quality,
                'num_satellites': num_satellites
            }
        except (IndexError, ValueError) as e:
            logging.error(f"Failed to parse GGA line: {e}")
            return None

    def close(self):
        if self.ser:
            try:
                self.ser.close()
            except Exception as e:
                logging.error(f"Failed to close serial port: {e}")
            finally:
                self.ser = None

if __name__ == "__main__":
    gps = SimpleGPS()

    if not gps.connect():
        logging.error("Failed to connect to GPS module.")
        sys.exit(1)

    try:
        while True:
            data = gps.read_data()
            if data:
                parsed_data = gps.parse_gga(data)
                if parsed_data:
                    logging.info(f"Parsed GGA data: {parsed_data}")
    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt caught, shutting down.")
    finally:
        gps.close()
        logging.info("Clean shutdown complete.")

