import serial
import time
import signal

class BluetoothConnection:
    def __init__(self, port='/dev/rfcomm4', baudrate=38400):
        self.port = port
        self.baudrate = baudrate
        self.connection = None

    def connect(self):
        try:
            self.connection = serial.Serial(self.port, self.baudrate)
            print("Connected to Bluetooth device at", self.port)
        except serial.SerialException as e:
            raise RuntimeError(f"Failed to connect to Bluetooth device at {self.port}: {e}")

    def send_command(self, command):
        try:
            self.connection.write(f"X{command}\n".encode())
            print(f"Sent command: {command}")
        except serial.SerialException as e:
            raise RuntimeError(f"Failed to send command: {e}")

    def close(self):
        if self.connection:
            self.connection.close()
            print("Disconnected from Bluetooth device")

def signal_handler(sig, frame):
    print("KeyboardInterrupt detected, cleaning up...")
    connection.close()
    exit(0)

signal.signal(signal.SIGINT, signal_handler)

connection = BluetoothConnection()
connection.connect()

try:
    while True:
        command = input("Enter command (type 'exit' to quit): ")
        if command.lower() == "exit":
            break
        connection.send_command(command)
        time.sleep(0.1)
finally:
    connection.close()

